          {clients.map(c => (
            <option key={c._id} value={c._id}>
              {c.fullName} ({c.email})
            </option>
          ))}
        </select>

        <select
          className="form__input"
          name="procedureId"
          value={editingAppointment.procedureId?._id || editingAppointment.procedureId}
          onChange={e => setEditingAppointment({ ...editingAppointment, procedureId: e.target.value })}
