            <option key={p._id} value={p._id}>
              {p.name}
            </option>
          ))}
        </select>

        <input
          className="form__input"
          type="datetime-local"
          name="startUtc"
          value={editingAppointment.startUtc}
          onChange={e => setEditingAppointment({ ...editingAppointment, startUtc: e.target.value })}
